const { parseTime, parseRange, formatMinutes } = require("./time-range");

function freeSlots(busy, dayStart, dayEnd, minLen = 1) {
  const start = parseTime(dayStart);
  const end = parseTime(dayEnd);
  if (end <= start) throw new Error("dayEnd must be after dayStart");
  if (typeof minLen !== "number" || Number.isNaN(minLen) || minLen < 0) {
    throw new Error("bad minLen: " + minLen);
  }

  const intervals = [];
  for (const r of busy) {
    const { start: s, end: e } = parseRange(r);
    const cs = Math.max(s, start);
    const ce = Math.min(e, end);
    if (cs < ce) intervals.push({ start: cs, end: ce });
  }

  intervals.sort((a, b) => a.start - b.start || a.end - b.end);

  const slots = [];
  let cursor = start;
  for (const iv of intervals) {
    if (iv.start > cursor && iv.start - cursor >= minLen) {
      slots.push(`${formatMinutes(cursor)}-${formatMinutes(iv.start)}`);
    }
    if (iv.end > cursor) cursor = iv.end;
  }
  if (end > cursor && end - cursor >= minLen) {
    slots.push(`${formatMinutes(cursor)}-${formatMinutes(end)}`);
  }
  return slots;
}

module.exports = { freeSlots };
