function parseDecimal(num) {
  const [coeff, expStr] = String(num).split("e");
  let exp = expStr ? Number(expStr) : 0;
  const dot = coeff.indexOf(".");
  let digits = coeff;
  if (dot !== -1) {
    digits = coeff.slice(0, dot) + coeff.slice(dot + 1);
    exp -= coeff.length - dot - 1;
  }
  return { mantissa: BigInt(digits), exp };
}

function splitBill(total, weights) {
  if (!Number.isInteger(total) || total < 0) throw new Error("bad total");
  if (!Array.isArray(weights) || !weights.length) throw new Error("bad weights");
  for (let i = 0; i < weights.length; i++) {
    const w = weights[i];
    if (typeof w !== "number" || !Number.isFinite(w) || !(w > 0)) {
      throw new Error("bad weights");
    }
  }

  const parsed = weights.map(parseDecimal);
  let minExp = parsed[0].exp;
  for (let i = 1; i < parsed.length; i++) {
    if (parsed[i].exp < minExp) minExp = parsed[i].exp;
  }

  const scaled = parsed.map(({ mantissa, exp }) => mantissa * (10n ** BigInt(exp - minExp)));
  const sum = scaled.reduce((a, b) => a + b, 0n);
  const totalBig = BigInt(total);

  const shares = new Array(weights.length);
  const remainders = new Array(weights.length);
  let floorSum = 0n;

  for (let i = 0; i < scaled.length; i++) {
    const numerator = totalBig * scaled[i];
    shares[i] = numerator / sum;
    remainders[i] = numerator % sum;
    floorSum += shares[i];
  }

  const leftover = Number(totalBig - floorSum);
  if (leftover > 0) {
    const order = scaled.map((_, i) => i);
    order.sort((a, b) => {
      if (remainders[b] > remainders[a]) return 1;
      if (remainders[b] < remainders[a]) return -1;
      return a - b;
    });
    for (let i = 0; i < leftover; i++) {
      shares[order[i]] += 1n;
    }
  }

  return shares.map(Number);
}

